-- Seed data for the program catalog (generated). Sources on the ESO Google Drive:
--   WPU Revised ESO Manual 2026, Ch. I Art. 3 Sec. 2: extension programs approved for FY 2025-2030 (BOR Res. No. 43 s. 2025)
--   2027 Monitoring Sheet: academic programs and the extension programs not in the manual's list
-- Idempotent: every insert is skipped when the row already exists.

UPDATE clusters SET name = 'Extension Cluster 1', track = 'extension' WHERE name = 'Cluster 1';
UPDATE clusters SET name = 'Extension Cluster 2', track = 'extension' WHERE name = 'Cluster 2';
UPDATE clusters SET name = 'Extension Cluster 3', track = 'extension' WHERE name = 'Cluster 3';
UPDATE colleges SET extension_cluster_id = (SELECT id FROM clusters WHERE name = 'Extension Cluster 1') WHERE code IN ('CAFES', 'CET', 'AMCEN', 'MEIC', 'ATBI', 'GREAT', 'PALBIORECC');
UPDATE colleges SET extension_cluster_id = (SELECT id FROM clusters WHERE name = 'Extension Cluster 2') WHERE code IN ('CED', 'CBEHM', 'CCJE', 'CPACD', 'CCAS', 'KIH', 'HALAL', 'SSRDEC');
UPDATE colleges SET extension_cluster_id = (SELECT id FROM clusters WHERE name = 'Extension Cluster 3') WHERE code IN ('CFINS', 'ICENAQUA', 'WPS-CORP', 'ABBA', 'TBTI', 'BMRS', 'BDLEC');
UPDATE colleges SET research_cluster_id = (SELECT id FROM clusters WHERE name = 'Research Cluster I') WHERE code IN ('ATBI', 'ICENAQUA', 'ABBA', 'TBTI', 'GREAT', 'PALBIORECC');
UPDATE colleges SET research_cluster_id = (SELECT id FROM clusters WHERE name = 'Research Cluster II') WHERE code IN ('SSRDEC', 'BMRS', 'WPS-CORP', 'BDLEC', 'HALAL');

UPDATE users SET academic_program_id = (SELECT ap.id FROM academic_programs ap WHERE ap.name = REPLACE(users.program, ' (*new)', '')) WHERE academic_program_id IS NULL AND program IS NOT NULL;

